tasks.command:
node -e 'const fs=require("fs"),path=require("path"),os=require("os");
const project=process.env.SCHEDULED_TASK_PROJECT||process.cwd();
const enc=String(project).replace(/[^a-zA-Z0-9]/g,"-");
const dir=path.join(os.homedir(),".claude","projects",enc);
const state=process.env.SCHEDULED_TASK_STATE_DIR||"";
const cursorFile=path.join(state,"autodoc-cursor.json");
const say=function(o){process.stdout.write(JSON.stringify(o));};
let cursor=null;
try{cursor=JSON.parse(fs.readFileSync(cursorFile,"utf8"));}catch(err){cursor=null;}
const last=Number(cursor&&(cursor.lastMessageMs||cursor.mtimeMs||cursor.at))||0;
let newest=0;
try{for(const f of fs.readdirSync(dir)){if(!f.endsWith(".jsonl"))continue;const m=fs.statSync(path.join(dir,f)).mtimeMs;if(m>newest)newest=m;}}catch(err){}
if(newest<=last){say({skip:true,reason:"no new conversations since "+(last>0?new Date(last).toISOString():"never")+(newest>0?"":" (no Claude transcripts in "+dir+")")});}
else{
const prompt="AutoDoc refresh for "+project+". New Claude Code conversations appeared since the last cursor (newest transcript mtime "+new Date(newest).toISOString()+").\n\n"
 +"The project transcripts live in "+dir+"; read the ones that changed after the cursor in $SCHEDULED_TASK_STATE_DIR/autodoc-cursor.json (read every transcript on a first run).\n"
 +"1. Extract what actually changed in this project (decisions, features, bugs, commands, file layout).\n"
 +"2. Update the project documentation: the Markdown files under docs/ and CLAUDE.md when it exists. Document only what the conversations support.\n"
 +"3. Keep long-lived notes in $SCHEDULED_TASK_STATE_DIR (for example autodoc-notes.md); the task tmp/ directory is wiped at the start of every run, so never keep anything you need across runs there.\n"
 +"4. Write the new cursor back to $SCHEDULED_TASK_STATE_DIR/autodoc-cursor.json as {\"lastMessageMs\":<newest transcript mtime in ms>,\"updatedAt\":\"<ISO timestamp>\"}.\n"
 +"5. Never write outside the task root ($SCHEDULED_TASK_DIR) and the project directory, then finish with a short summary of the documentation updates.";
say({prompt:prompt});
}'
